ALTER TABLE permissions ADD COLUMN deleted_at DATETIME(6) NULL, ADD COLUMN deleted_by TEXT NULL;
ALTER TABLE roles ADD COLUMN deleted_at DATETIME(6) NULL, ADD COLUMN deleted_by TEXT NULL;
ALTER TABLE role_permissions ADD COLUMN deleted_at DATETIME(6) NULL, ADD COLUMN deleted_by TEXT NULL;
ALTER TABLE role_bindings ADD COLUMN deleted_at DATETIME(6) NULL, ADD COLUMN deleted_by TEXT NULL;
ALTER TABLE authorization_policy_versions ADD COLUMN deleted_at DATETIME(6) NULL, ADD COLUMN deleted_by TEXT NULL;
ALTER TABLE authorization_subject_groups ADD COLUMN deleted_at DATETIME(6) NULL, ADD COLUMN deleted_by TEXT NULL;
ALTER TABLE authorization_processed_events ADD COLUMN deleted_at DATETIME(6) NULL, ADD COLUMN deleted_by TEXT NULL;
ALTER TABLE authorization_outbox_events ADD COLUMN deleted_at DATETIME(6) NULL, ADD COLUMN deleted_by TEXT NULL;
CREATE TRIGGER permissions_audit_bi BEFORE INSERT ON permissions FOR EACH ROW SET NEW.created_at=CURRENT_TIMESTAMP(6),NEW.created_by=NULLIF(TRIM(@app_actor_id),''),NEW.updated_at=CURRENT_TIMESTAMP(6),NEW.updated_by=NULLIF(TRIM(@app_actor_id),''),NEW.version=1,NEW.deleted_at=NULL,NEW.deleted_by=NULL;
CREATE TRIGGER permissions_audit_bu BEFORE UPDATE ON permissions FOR EACH ROW SET NEW.created_at=OLD.created_at,NEW.created_by=OLD.created_by,NEW.updated_at=CURRENT_TIMESTAMP(6),NEW.updated_by=NULLIF(TRIM(@app_actor_id),''),NEW.version=OLD.version+1,NEW.deleted_by=CASE WHEN NEW.deleted_at IS NULL THEN NULL WHEN OLD.deleted_at IS NULL THEN NULLIF(TRIM(@app_actor_id),'') ELSE OLD.deleted_by END;
CREATE TRIGGER permissions_audit_bd BEFORE DELETE ON permissions FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='physical delete is forbidden';
